function fun_compare_sande(starttime,endtime){var attrstarttime=starttime.split(':');var attrendtime=endtime.split(':');for(var i=0;i<3;i++){if(!attrstarttime[i].match("^[0-9]+$")||!attrendtime[i].match("^[0-9]+$")){return true;}}
var start=parseInt(attrstarttime[0])*3600+parseInt(attrstarttime[1])*60+parseInt(attrstarttime[2]);var end=parseInt(attrendtime[0])*3600+parseInt(attrendtime[1])*60+parseInt(attrendtime[2]);if(start>end){return true;}}
function fun_on_weekday_alldays(){var bchecked=document.getElementById("check_weekday_alldays").checked;if(bchecked==true){document.getElementById("check_weekday_monday").checked=true;document.getElementById("check_weekday_tuesday").checked=true;document.getElementById("check_weekday_wednesday").checked=true;document.getElementById("check_weekday_thursday").checked=true;document.getElementById("check_weekday_friday").checked=true;document.getElementById("check_weekday_saturday").checked=true;document.getElementById("check_weekday_sunday").checked=true;}else{$("#check_weekday_monday,#check_weekday_tuesday,#check_weekday_wednesday,#check_weekday_thursday,#check_weekday_friday,#check_weekday_saturday,#check_weekday_sunday").removeAttr("checked");if(g_current_set_day==1){document.getElementById("check_weekday_monday").checked=true;}else if(g_current_set_day==2){document.getElementById("check_weekday_tuesday").checked=true;}else if(g_current_set_day==3){document.getElementById("check_weekday_wednesday").checked=true;}else if(g_current_set_day==4){document.getElementById("check_weekday_thursday").checked=true;}else if(g_current_set_day==5){document.getElementById("check_weekday_friday").checked=true;}else if(g_current_set_day==6){document.getElementById("check_weekday_saturday").checked=true;}else if(g_current_set_day==7){document.getElementById("check_weekday_sunday").checked=true;}}}
function fun_wireless_checkbox_change(){var checkboxall=$("#div_setup_weekday_select .wireless_checkbox_change").length;var checked=$("#div_setup_weekday_select .wireless_checkbox_change:checked").length;if(checked<checkboxall){$("#check_weekday_alldays").prop("checked",false);}else{$("#check_weekday_alldays").prop("checked",true);}}